import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def isp(v):
    if v < 2:
        return False
    d = 2
    while d * d <= v:
        if v % d == 0:
            return False
        d += 1
    return True
best = 0
cur = 0
for x in a:
    if isp(x):
        cur += 1
        if cur > best:
            best = cur
    else:
        cur = 0
print(best)

